use vstd::prelude::*;

verus! {

fn swap_first_and_last(a: &Vec<i32>) -> (result: Vec<i32>)
    ensures
        // Result length is preserved.
        result.len() == a.len(),

        // If the input has 0 or 1 element, the result is identical to the input.
        a.len() <= 1 ==> (forall|i: int|
            0 <= i && i < a.len() ==> result[i] == (*a)[i]
        ),

        // If the input has at least 2 elements, the first/last are swapped...
        a.len() > 1 ==> result[0] == (*a)[a.len() - 1],
        a.len() > 1 ==> result[a.len() - 1] == (*a)[0],

        // ...and all interior elements are unchanged.
        a.len() > 1 ==> (forall|i: int|
            0 < i && i < a.len() - 1 ==> result[i] == (*a)[i]
        ),
{
    let n = a.len();
    if n <= 1 {
        return a.clone();
    }

    let mut result = a.clone();
    result.swap(0, n - 1);
    result
}

} // verus!